    aim:"Write arithmetic operations and handle division by zero.",requirements:"Browser Python runner or Python 3.",language:"python",filename:"calculator.py",code:"def calculate(a, b, op):\n    if op == '+': return a + b\n    if op == '-': return a - b\n    if op == '*': return a * b\n    if op == '/':\n        if b == 0: raise ValueError('Cannot divide by zero')\n        return a / b\n    raise ValueError('Unknown operator')\n\nfor op in ['+', '-', '*', '/']:\n    print(op, calculate(12, 3, op))",steps:["Predict outputs for 12 and 3.","Run the program and record each result.","Change divisor to 0 and observe a controlled error.","Add an operator such as integer division and test it."],expected:"+ 15\n- 9\n* 36\n/ 4.0",viva:["What is the difference between / and //?","How is zero division handled?","Why use a function?"],faults:["Handle unknown operators.","Do not silently return a misleading result for invalid input."]
