  make("ai-lab","Breadth-first search",{
    aim:"Implement BFS and observe first-in-first-out frontier processing.",requirements:"Browser Python runner or Python 3.",language:"python",filename:"bfs.py",code:"from collections import deque\ngraph = {\n    'A': ['B', 'C'],\n    'B': ['D'],\n    'C': ['E'],\n    'D': [], 'E': []\n}\ndef bfs(start):\n    q = deque([start])\n    seen = {start}\n    order = []\n    while q:\n        current = q.popleft()\n        order.append(current)\n        for nxt in graph[current]:\n            if nxt not in seen:\n                seen.add(nxt)\n                q.append(nxt)\n    return order\nprint(bfs('A'))",steps:["Draw the graph edges A→B,C; B→D; C→E.","Predict the BFS order using a queue.","Execute the program.","Swap the order of A's neighbours and compare traversal order.","Explain whether the edge-distance result changes."],expected:"['A', 'B', 'C', 'D', 'E']",viva:["Why use deque?","When should visited be updated?","What is BFS time complexity with adjacency lists?"],faults:["Use popleft for queue order.","Mark visited on enqueue to avoid duplicates."]
  }),
  make("ai-lab","8-puzzle",{
    aim:"Represent the 8-puzzle as a state and generate legal moves of the blank tile.",requirements:"Browser Python runner or Python 3.",language:"python",filename:"puzzle.py",code:"state = (1,2,3,4,0,5,7,8,6)\n\ndef neighbours(board):\n    z = board.index(0)\n    r, c = divmod(z, 3)\n    results = []\n    for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:\n        nr, nc = r + dr, c + dc\n        if 0 <= nr < 3 and 0 <= nc < 3:\n            j = nr*3 + nc\n            nxt = list(board)\n            nxt[z], nxt[j] = nxt[j], nxt[z]\n            results.append(tuple(nxt))\n    return results\n\nfor b in neighbours(state): print(b)",steps:["Sketch the 3×3 board where 0 denotes blank.","Predict four legal moves from the central blank.","Run code to generate neighbours.","Move the blank to a corner and predict two legal moves.","Extend with BFS and a visited set to search for a goal."],expected:"Four distinct neighbour states are printed for the central blank.",viva:["Why use immutable tuples for states?","What is branching factor?","How do we avoid revisiting a state?"],faults:["Check row/column limits before swapping.","This exercise generates neighbours; it does not claim to solve arbitrary puzzles yet."]
  })
